package com.hbm.blocks.machine.rbmk;
import com.hbm.tileentity.ModRBMKBlockEntities; import com.hbm.tileentity.machine.rbmk.*; import net.minecraft.core.BlockPos; import net.minecraft.world.level.block.entity.BlockEntityType; import net.minecraft.world.level.block.state.BlockState;
public class RBMKAbsorber extends RBMKBase { public final double heatMult; public RBMKAbsorber(Properties properties) { this(properties, 1D); } public RBMKAbsorber(Properties properties, double heatMult) { super(properties); this.heatMult = heatMult; } @Override protected BlockEntityType<? extends BlockEntityRBMKBase> beType() { return ModRBMKBlockEntities.RBMK_ABSORBER.get(); } @Override protected BlockEntityRBMKBase createCore(BlockPos pos, BlockState state) { return new BlockEntityRBMKAbsorber(pos, state); } }
